CREATE TABLE IF NOT EXISTS shop_distribution_attribution(order_id BIGINT NOT NULL,member_id BIGINT NOT NULL,depth INT NOT NULL,PRIMARY KEY(order_id,depth),INDEX attribution_owner(member_id));
